reproduction_scripts.run-doss-material.ps1:
param([string]$Tag='before', [switch]$Comparison, [switch]$Production)
$ErrorActionPreference='Stop'
$lockPath='D:/tetherbound/RENDER_LOCK.json'
$old=Get-Content -LiteralPath $lockPath -Raw | ConvertFrom-Json
if ($old.held_by) { throw "Render lock held by $($old.held_by)" }
$env:APPDATA='D:/tetherbound/visual-acceptance-local/profile'
$logBase="D:/tetherbound/visual-acceptance-local/doss-material-$Tag"
$record=@{held_by='combat';since_utc=[DateTime]::UtcNow.ToString('o');pid=0;shell_pid=$PID}
$record | ConvertTo-Json | Set-Content -LiteralPath $lockPath
try {
  $argsList=@('--path','D:/tetherbound/visual-acceptance','--rendering-method','gl_compatibility','--borderless','--position','0,0','--resolution','1920x1080','--fixed-fps','60','--script','D:/tetherbound/visual-acceptance-local/capture_doss_material.gd','--','--act','--activity=doss','--save=res://tests/fixtures/f03_lure_saves/S07-exit-band3-plus-1wood-1fiber.json.gz',"--capture-dir=D:/tetherbound/visual-acceptance/shots/doss-material-$Tag")
  if ($Comparison) { $argsList = $argsList | ForEach-Object { if ($_ -eq 'D:/tetherbound/visual-acceptance-local/capture_doss_material.gd') { 'D:/tetherbound/visual-acceptance-local/capture_doss_comparison.gd' } else { $_ } } }
  if ($Production) { $argsList = $argsList | ForEach-Object { if ($_ -eq 'D:/tetherbound/visual-acceptance-local/capture_doss_material.gd') { 'D:/tetherbound/visual-acceptance-local/capture_doss_production.gd' } else { $_ } } }
  $proc=Start-Process 'D:/Tetherbound-tools/godot/Godot_v4.7-stable_win64.exe' -ArgumentList $argsList -WindowStyle Hidden -RedirectStandardOutput "$logBase.log" -RedirectStandardError "$logBase.err" -PassThru
  $record.pid=$proc.Id
  $record | ConvertTo-Json | Set-Content -LiteralPath $lockPath
  if (-not $proc.WaitForExit(600000)) { $proc.Kill(); throw 'Capture exceeded ten-minute deadline' }
  $proc.Refresh()
  Write-Output "$Tag exit: $($proc.ExitCode)"
  if (Select-String -LiteralPath "$logBase.err" -Pattern 'SCRIPT ERROR:|^ERROR:' -Quiet) { throw 'Capture emitted error diagnostics' }
  if ($proc.ExitCode -ne 0) { throw 'Capture failed; inspect logs' }
} finally {
  $current=Get-Content -LiteralPath $lockPath -Raw | ConvertFrom-Json
  if ($current.shell_pid -eq $PID) { '{}' | Set-Content -LiteralPath $lockPath }
}
